cat > src/scanner.js <<'EOF'
export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isLetter(c) || isDigit(c) || c === '_'

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 4 + 1
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (i, reason) => { throw new ScanError(lines[i], cols[i], reason) }
  const tokens = []
  const push = (i, kind, body) => tokens.push({ line: lines[i], col: cols[i], kind, body })

  // digit run with single underscores between digits; returns end index
  const run = (i, ok) => {
    if (!ok(cs[i])) return i
    i++
    for (;;) {
      if (ok(cs[i])) i++
      else if (cs[i] === '_' && ok(cs[i + 1])) i += 2
      else return i
    }
  }

  let i = 0
  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) fail(start, 'unterminated block comment')
        if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else i++
      }
      continue
    }
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (isIdPart(cs[j])) j++
      const s = cs.slice(i, j).join('')
      push(i, KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i + 1
      let bad = false
      const p = (cs[i + 1] || '').toLowerCase()
      if (ch === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        j = i + 2
        const e = run(j, ok)
        if (e === j) bad = true
        j = e
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (isIdPart(cs[j])) {
        bad = true
        while (isIdPart(cs[j])) j++
      }
      const s = cs.slice(i, j).join('')
      if (bad) fail(i, `invalid number ${s}`)
      push(i, 'number', s)
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let v = ''
      for (;;) {
        if (j >= n) fail(i, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') { v += d; j++; continue }
        const e = cs[j + 1]
        if (e === undefined) fail(i, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { v += simple[e]; j += 2 }
        else if (e === 'x') {
          if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
            v += String.fromCharCode(parseInt(cs[j + 2] + cs[j + 3], 16))
            j += 4
          } else fail(j, 'invalid escape \\x')
        } else if (e === 'u') {
          if (cs[j + 2] !== '{') fail(j, 'invalid escape \\u')
          let k = j + 3
          while (isHex(cs[k])) k++
          const hex = cs.slice(j + 3, k).join('').replace(/^0+(?=.)/, '')
          if (cs[k] !== '}' || k === j + 3 || hex.length > 6 || parseInt(hex, 16) > 0x10ffff) {
            fail(j, 'invalid escape \\u')
          }
          v += String.fromCodePoint(parseInt(hex, 16))
          j = k + 1
        } else fail(j, `invalid escape \\${e}`)
      }
      push(i, 'string', JSON.stringify(v))
      i = j
      continue
    }
    const two = ch + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { push(i, 'punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { push(i, 'punct', ch); i++; continue }
    fail(i, `unexpected character ${ch}`)
  }
  return tokens
}
