{"description":"Write cli.js and test","command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const usage = 'error: usage: cli.js waves|explain|pack <workers>'
let mode = args[0]
let workers = 0
if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
  // ok
} else if (mode === 'pack' && args.length === 2) {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(usage)

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const NAME = /^[A-Za-z0-9_.\-]+$/
const tasks = new Map()
const depUses = []
const edges = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const n = i + 1
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (tasks.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    tasks.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) if (!NAME.test(x)) fail(`error: line ${n}: invalid task name ${x}`)
    if (!edges.has(w[1])) edges.set(w[1], new Set())
    for (const d of w.slice(2)) edges.get(w[1]).add(d)
    depUses.push(...w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
for (const x of depUses) if (!tasks.has(x)) fail(`error: unknown task ${x}`)

const names = [...tasks.keys()].sort()
const deps = new Map(names.map(k => [k, [...(edges.get(k) || [])].sort()]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of deps.get(u)) {
    if (state.get(v) === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!state.has(v)) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.has(k)) dfs(k)

// start/finish/depth in topological (memoized) order
const start = new Map(), finish = new Map(), depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of deps.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
