{"file_path":"src/formula.js","content":"const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function colIndex(letters) {
  let n = 0
  for (const c of letters.toUpperCase()) n = n * 26 + (c.charCodeAt(0) - 64)
  return n
}
export function colName(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  return String.fromCharCode(64 + Math.floor((n - 1) / 26)) + String.fromCharCode(65 + ((n - 1) % 26))
}

// Returns {col,row} or null when outside the addressable range.
export function parseAddr(word) {
  const m = ADDR.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1]), row }
}

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ k: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { toks.push({ k: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

class Fail extends Error {}

// Returns an AST (with .misplaced flag at the root) or null when the grammar rejects the text.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  let misplaced = false
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const peekOp = () => (p < toks.length && toks[p].k === 'op' ? toks[p].v : null)

  function cmp() {
    let l = add()
    for (;;) {
      const o = peekOp()
      if (o && ['=', '<>', '<', '<=', '>', '>='].includes(o)) {
        p++
        l = { t: 'bin', op: o, l, r: add() }
      } else return l
    }
  }
  function add() {
    let l = mul()
    for (;;) {
      const o = peekOp()
      if (o === '+' || o === '-') { p++; l = { t: 'bin', op: o, l, r: mul() } } else return l
    }
  }
  function mul() {
    let l = pow()
    for (;;) {
      const o = peekOp()
      if (o === '*' || o === '/') { p++; l = { t: 'bin', op: o, l, r: pow() } } else return l
    }
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    const o = peekOp()
    if (o === '-' || o === '+') { p++; return { t: 'un', op: o, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new Fail()
    const t = toks[p]
    if (t.k === 'num') { p++; return { t: 'num', v: t.v } }
    if (t.k === 'op') {
      if (t.v === '(') {
        p++
        const e = cmp()
        if (!isOp(')')) throw new Fail()
        p++
        return e
      }
      throw new Fail()
    }
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw new Fail()
        }
      }
      return { t: 'call', name: t.v.toUpperCase(), args }
    }
    const up = t.v.toUpperCase()
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw new Fail()
      const w2 = toks[p].v
      p++
      if (isOp('(')) throw new Fail()
      return { t: 'range', a: t.v, b: w2, direct: false }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', w: t.v }
  }
  function arg() {
    const e = cmp()
    if (e.t === 'range') e.direct = true
    return e
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    const mark = (n) => {
      if (!n) return
      if (n.t === 'range' && !n.direct) misplaced = true
      if (n.t === 'bin') { mark(n.l); mark(n.r) }
      if (n.t === 'un') mark(n.e)
      if (n.t === 'call') n.args.forEach(mark)
    }
    mark(e)
    return { t: 'root', e, misplaced }
  } catch (err) {
    if (err instanceof Fail) return null
    throw err
  }
}

export function rangeCells(r) {
  const a = parseAddr(r.a)
  const b = parseAddr(r.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
    for (let w = Math.min(a.row, b.row); w <= Math.max(a.row, b.row); w++) out.push(colName(c) + w)
  }
  return out
}

export function collectDeps(ast) {
  const set = new Set()
  const walk = (n) => {
    switch (n.t) {
      case 'root': return walk(n.e)
      case 'bin': walk(n.l); return walk(n.r)
      case 'un': return walk(n.e)
      case 'call': return n.args.forEach(walk)
      case 'ref': {
        const a = parseAddr(n.w)
        if (a) set.add(colName(a.col) + a.row)
        return
      }
      case 'range': {
        const cs = rangeCells(n)
        if (cs) cs.forEach((c) => set.add(c))
        return
      }
    }
  }
  walk(ast)
  return set
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula, parseAddr, colName, rangeCells } from './formula.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ k: 'err', v: e })
const num = (v) => ({ k: 'num', v })
const isErr = (v) => v.k === 'err'

export function formatValue(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'err': return v.v
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRORS.includes(content)) return err(content)
  return { k: 'text', v: content }
}

function finite(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}

// Numeric reading of a non-error value; returns a number or an error value.
function toNum(v) {
  if (v.k === 'num') return v.v
  if (v.k === 'bool') return v.v ? 1 : 0
  return err('#VALUE!')
}

function cpCompare(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const RANK = { num: 0, text: 1, bool: 2 }
function compare(a, b) {
  if (a.k !== b.k) return RANK[a.k] - RANK[b.k]
  if (a.k === 'text') return cpCompare(a.v, b.v)
  if (a.k === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

export function evaluateAll(cells) {
  const memo = new Map()
  const stack = new Set()
  const parsed = new Map()

  function cellValue(addr) {
    if (memo.has(addr)) return memo.get(addr)
    if (!cells.has(addr)) return num(0)
    if (stack.has(addr)) return err('#CYCLE!')
    const content = cells.get(addr)
    let v
    if (content.startsWith('=')) {
      stack.add(addr)
      v = evalFormula(content.slice(1))
      stack.delete(addr)
    } else v = literal(content)
    memo.set(addr, v)
