function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const res = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) res.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const sides = [mine, theirs]
  const out = []
  let conflict = false
  const emit = (kind, lines, extra) => {
    if (mode === 'regions') out.push(extra ?? `${kind} ${lines.length}`)
    else out.push(...lines)
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const first = all[k++]
    const rs = first.bs
    let re = first.be
    const group = [first]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) emit('stable', base.slice(pos, rs))
    pos = re
    const baseLines = base.slice(rs, re)
    const rep = sides.map((lines, s) => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseLines
      const f = cs[0], l = cs[cs.length - 1]
      const maxBe = Math.max(...cs.map(c => c.be))
      return lines.slice(f.ss - (f.bs - rs), l.se + (re - maxBe))
    })
    const [m, t] = rep
    if (eq(m, t)) emit('both', m)
    else if (eq(m, baseLines)) emit('theirs', t)
    else if (eq(t, baseLines)) emit('mine', m)
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseLines)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    }
  }
  if (base.length > pos) emit('stable', base.slice(pos))
  return { out, conflict }
}
