{"file_path":"src/parse.js","content":"function err(message) {
  const e = new Error(message)
  e.isElectionError = true
  return e
}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const word = words[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 2) throw err(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) throw err(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = words.slice(1)
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 3) throw err(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!COUNT.test(words[1])) throw err(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of words.slice(2)) {
        if (!candidates.includes(name)) throw err(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(words[1]), ranking: words.slice(2) })
    } else {
      throw err(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) throw err('error: no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // per round: Map name -> votes
  const rounds = []
  let winner = null
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranking.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    history.push(votes)
    const listing = [...votes.entries()].sort((a, b) =>
      a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
    const round = { listing, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) break
    const top = listing.find(([, v]) => v * 2n > active)
    if (top) {
      winner = top[0]
      break
    }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let tied = [...continuing].filter((c) => votes.get(c) === min)
    for (let r = 0; r < history.length && tied.length > 1; r++) {
      let lo = null
      for (const c of tied) {
        const v = history[r].get(c)
        if (lo === null || v < lo) lo = v
      }
      const next = tied.filter((c) => history[r].get(c) === lo)
      if (next.length < tied.length) {
        tied = next
        r = -1
      }
    }
    tied.sort()
    const out = tied[tied.length - 1]
    continuing.delete(out)
    round.eliminated = out
  }
  return { rounds, winner }
}
"}

