{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'

class ConfError extends Error {}
const fail = (m) => { throw new ConfError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

const table = () => ({ t: 'table', m: new Map(), hdr: false })
const scalar = (t, v) => ({ t, v })

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  skip() { while (isWs(this.s[this.i])) this.i++ }
  // next significant char; comment characters count as end of line
  peek() {
    this.skip()
    const c = this.s[this.i]
    return c === '#' || c === ';' ? undefined : c
  }
}

function parseString(L, q) {
  const s = L.s
  L.i++
  let out = ''
  if (q === "'") {
    const e = s.indexOf("'", L.i)
    if (e < 0) fail('unterminated string')
    out = s.slice(L.i, e)
    L.i = e + 1
    return out
  }
  for (;;) {
    const c = s[L.i]
    if (c === undefined) fail('unterminated string')
    if (c === '"') { L.i++; return out }
    if (c === '\\') {
      const n = s[L.i + 1]
      if (n === undefined) fail('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, n)) { out += map[n]; L.i += 2; continue }
      if (n === 'u') {
        const h = s.slice(L.i + 2, L.i + 6)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 6
        continue
      }
      fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(L.i + 1)))
    }
    out += c
    L.i++
  }
}

function parseName(L) {
  const c = L.s[L.i]
  if (c === '"' || c === "'") return parseString(L, c)
  const st = L.i
  while (isBare(L.s[L.i])) L.i++
  if (L.i === st) fail('expected a name')
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  L.skip()
  const parts = [parseName(L)]
  for (;;) {
    L.skip()
    if (L.s[L.i] !== '.') return parts
    L.i++
    L.skip()
    parts.push(parseName(L))
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseValue(L, base) {
  const c = L.peek()
  if (c === undefined || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") return scalar('string', parseString(L, c))
  if (c === '[') return parseArray(L, base)
  if (c === '{') return parseInline(L, base)
  const st = L.i
  while (L.i < L.s.length && !isWs(L.s[L.i]) && !',]};'.includes(L.s[L.i])) L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true') return scalar('boolean', true)
  if (w === 'false') return scalar('boolean', false)
  if (INT.test(w)) return scalar('integer', BigInt(w.replace(/_/g, '')))
  if (FLOAT.test(w)) return scalar('float', Number(w.replace(/_/g, '')))
  fail('invalid value ' + w)
}

function parseArray(L, base) {
  L.i++
  const node = { t: 'array', items: [], aot: false }
  if (L.peek() === ']') { L.i++; return node }
  for (;;) {
    if (L.peek() === undefined) fail('unterminated array')
    node.items.push(parseValue(L, base))
    const c = L.peek()
    if (c === ']') { L.i++; return node }
    if (c !== ',') fail('unterminated array')
    L.i++
    if (L.peek() === ']') { L.i++; return node }
  }
}

function parseInline(L, base) {
  L.i++
  const node = table()
  if (L.peek() === '}') { L.i++; return node }
  for (;;) {
    if (L.peek() === undefined) fail('unterminated inline table')
