  for (const a of args) vals.push(...argValues(a))
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (nm === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const ns = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    ns.push(x.v)
  }
  switch (nm) {
    case 'SUM': return fin(ns.reduce((a, b) => a + b, 0))
    case 'AVG': return fin(ns.reduce((a, b) => a + b, 0) / ns.length)
    case 'MIN': return num(Math.min(...ns))
    case 'MAX': return num(Math.max(...ns))
  }
  return err('#ERR!')
}

