    if (!(e instanceof Fail)) throw e
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  process.stdout.write(out)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const results = []
  const counts = new Map()
  let started = false
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const fail = (r) => new Fail(`error: line ${i + 1}: ${r}`)
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const d = t[0]
    const num = (v, field, least) => {
      if (!COUNT.test(v) || BigInt(v) < BigInt(least)) throw fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const early = () => { if (started) throw fail('declarations must come before the first event') }
    if (d === 'bucket') {
      if (t.length !== 5) throw fail('expected bucket <name> <capacity> <refill> <per>')
      early()
      if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
      const capacity = num(t[2], 'capacity', 1)
      const refill = num(t[3], 'refill', 0)
      const per = num(t[4], 'per', 1)
      if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per, st: new Map() })
    } else if (d === 'window') {
      if (t.length !== 4) throw fail('expected window <name> <limit> <span>')
      early()
      if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
      const limit = num(t[2], 'limit', 0)
      const span = num(t[3], 'span', 1)
      if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { name: t[1], kind: 'window', limit, span, st: new Map() })
    } else if (d === 'route') {
      if (t.length < 3) throw fail('expected route <prefix> <policy>...')
      early()
      if (!NAME.test(t[1])) throw fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) throw fail(`prefix ${t[1]} is routed twice`)
      const ps = []
      for (const n of t.slice(2)) {
        if (!policies.has(n)) throw fail(`unknown policy ${n}`)
        ps.push(policies.get(n))
      }
      routes.set(t[1], ps)
    } else if (d === 'event') {
      if (t.length !== 3) throw fail('expected event <tick> <key>')
      const tick = num(t[1], 'tick', 0)
      if (!NAME.test(t[2])) throw fail(`invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) throw fail(`tick ${tick} is before tick ${lastTick}`)
      started = true
      lastTick = tick
      const key = t[2]
      let best = null
      for (const [p, ps] of routes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
      let denied = null
      if (best !== null) {
        const ps = routes.get(best)
        const states = ps.map((p) => {
          let s = p.st.get(key)
          if (!s) {
            s = p.kind === 'bucket' ? { units: p.capacity * p.per, last: tick } : { ticks: [] }
            p.st.set(key, s)
          }
          if (p.kind === 'bucket') {
            s.units += p.refill * (tick - s.last)
            const cap = p.capacity * p.per
            if (s.units > cap) s.units = cap
            s.last = tick
          } else {
            const cut = tick - p.span
            s.ticks = s.ticks.filter((x) => x > cut)
          }
          return s
        })
        for (let j = 0; j < ps.length; j++) {
          const p = ps[j], s = states[j]
          const ok = p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
          if (!ok) { denied = p.name; break }
        }
        if (denied === null) {
          for (let j = 0; j < ps.length; j++) {
            if (ps[j].kind === 'bucket') states[j].units -= ps[j].per
            else states[j].ticks.push(tick)
          }
        }
      }
      results.push(`${t[1]} ${key} ${denied === null ? 'allow' : 'deny ' + denied}`)
      const c = counts.get(key) || { a: 0, d: 0 }
      if (denied === null) c.a++; else c.d++
      counts.set(key, c)
    } else {
      throw fail(`unknown directive ${d}`)
    }
  }
  if (mode === 'replay') return results.map((r) => r + '\n').join('')
  let o = '', ta = 0, td = 0
  for (const k of [...counts.keys()].sort()) {
    const c = counts.get(k)
    o += `${k} allowed=${c.a} denied=${c.d}\n`
    ta += c.a; td += c.d
  }
  return o + `total allowed=${ta} denied=${td}\n`
}
