cat > src/uri.js <<'EOF'
export class UriError extends Error {}

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  let host = rest, port
  if (colon >= 0) { host = rest.slice(0, colon); port = rest.slice(colon + 1) }
  return { userinfo, host, port }
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function normPct(s) {
  return s.replace(/%([0-9a-fA-F]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

function checkPct(label, s) {
  if (s !== undefined && /%(?![0-9a-fA-F]{2})/.test(s)) {
    throw new UriError(`the ${label} has a truncated percent-encoding`)
  }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function serialize(c) {
  const p = normalizeParts(c)
  let r = ''
  if (p.scheme !== undefined) r += p.scheme + ':'
  if (p.authority !== undefined) r += '//' + p.authority
  r += p.path
  if (p.query !== undefined) r += '?' + p.query
  if (p.fragment !== undefined) r += '#' + p.fragment
  return r
}

function normalizeParts(c) {
  const scheme = c.scheme === undefined ? undefined : lowerAscii(c.scheme)
  let authority
  let ui, host, port
  if (c.authority !== undefined) ({ userinfo: ui, host, port } = splitAuthority(c.authority))
  checkPct('path', c.path)
  checkPct('userinfo', ui)
  checkPct('host', host)
  checkPct('query', c.query)
  checkPct('fragment', c.fragment)
