import { readFileSync } from 'node:fs'

const fail = (msg) => { process.stderr.write(msg + '\n'); process.exit(2) }
const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
let seenBallot = false
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (cands !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (t[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    seenBallot = true
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push([BigInt(t[1]), t.slice(2)])
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (cands === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b[0], 0n)
const alive = new Set(cands)
const hist = new Map(cands.map((c) => [c, []]))
const out = []
let roundNo = 0
let result
for (;;) {
  roundNo++
  const cnt = new Map([...alive].map((c) => [c, 0n]))
  let active = 0n
  for (const [k, names] of ballots) {
    const c = names.find((x) => alive.has(x))
    if (c !== undefined) { cnt.set(c, cnt.get(c) + k); active += k }
  }
  for (const [c, v] of cnt) hist.get(c).push(v)
  const order = [...cnt.keys()].sort((a, b) => (cnt.get(a) === cnt.get(b) ? (a < b ? -1 : 1) : cnt.get(a) > cnt.get(b) ? -1 : 1))
  let line = `round ${roundNo}: ` + order.map((c) => `${c}=${cnt.get(c)}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) { result = 'no winner'; break }
  const w = order.find((c) => cnt.get(c) * 2n > active)
  if (w !== undefined) { result = `winner ${w}`; break }
  let set = [...alive]
  const min = set.reduce((m, c) => (cnt.get(c) < m ? cnt.get(c) : m), cnt.get(set[0]))
  set = set.filter((c) => cnt.get(c) === min)
  for (let r = 0; r < roundNo && set.length > 1; ) {
    const vals = set.map((c) => hist.get(c)[r])
    const lo = vals.reduce((m, v) => (v < m ? v : m))
    if (vals.every((v) => v === lo)) { r++; continue }
    set = set.filter((c) => hist.get(c)[r] === lo)
    r = 0
  }
  const el = set.reduce((a, b) => (a > b ? a : b))
  alive.delete(el)
  out.push(`eliminated ${el}`)
}
if (mode === 'tally') process.stdout.write(`rounds ${roundNo}\n${result}\n`)
else process.stdout.write(out.join('\n') + `\n${result}\n`)
