import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(mode)) fail('usage: cli.js merge|merge2|regions')
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const sides = { mine, theirs }
  const all = [...changes(base, mine, 'mine'), ...changes(base, theirs, 'theirs')]
  all.sort((a, b) => a.bs - b.bs) // stable: mine first on ties
  const out = []
  let conflict = false
  const stable = (a, b) => {
    if (b > a) {
      if (mode === 'regions') out.push(`stable ${b - a}`)
      else out.push(...base.slice(a, b))
    }
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const group = [all[k++]]
    const rs = group[0].bs
    let re = group[0].be
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(pos, rs)
    pos = re
    const baseL = base.slice(rs, re)
    let label, res
    const repl = who => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseL
      const s0 = Math.min(...cs.map(c => c.bs)), e1 = Math.max(...cs.map(c => c.be))
      const first = cs.reduce((a, c) => (c.bs < a.bs ? c : a))
      const last = cs.reduce((a, c) => (c.be > a.be ? c : a))
      return sides[who].slice(first.ss - (s0 - rs), last.se + (re - e1))
    }
    if (group.length === 1) {
      label = group[0].who
      res = sides[label].slice(group[0].ss, group[0].se)
    } else {
      const m = repl('mine'), t = repl('theirs')
      if (eq(m, t)) { label = 'both'; res = m }
      else if (eq(m, baseL)) { label = 'theirs'; res = t }
      else if (eq(t, baseL)) { label = 'mine'; res = m }
      else {
        label = 'conflict'
        conflict = true
        if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
        else {
          out.push('<<<<<<< mine', ...m)
          if (mode === 'merge') out.push('||||||| base', ...baseL)
          out.push('=======', ...t, '>>>>>>> theirs')
        }
        continue
      }
    }
    if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  stable(pos, base.length)
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
